insert into public.outreach_records (
  category,
  platform,
  contact_name,
  contact_email,
  song_title,
  pitch,
  raw_data
)
values
  ('INFLUENCER', 'TikTok', 'Amanda LaCount', 'contact@amandalacount.com', 'OCEAN GIRL', 'Hi Amanda! I love how you use your platform to celebrate body positivity and high‑energy dance. My new single ''OCEAN GIRL'' is a vibrant dance‑pop/tropical house track inspired by artists like The 1975 and Kygo. I think your unique freestyle flair could make an amazing choreography that empowers your audience. I''d love to send you the song and see how we can collaborate on a TikTok dance challenge! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"793.5K"}'),
  ('INFLUENCER', 'TikTok', 'Kaycee Rice', 'info@kayceerice.com', 'OCEAN GIRL', 'Hey Kaycee! I''m a big fan of your creative and expressive dance videos. I''ve just released a new song called ''OCEAN GIRL'' that blends dance‑pop and alt‑pop vibes with lush tropical house elements. I think your innovative choreography could bring the song to life on TikTok. Would you be interested in crafting a dance concept around it? I''d love to share more details! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"1.9M"}'),
  ('INFLUENCER', 'TikTok', 'Rybka Twins (Sam & Teagan)', 'therybkatwinsbusiness@hotmail.com', 'OCEAN GIRL', 'Hello Sam and Teagan! I admire how you synchronize your moves so flawlessly. My new single ''OCEAN GIRL'' has a fun, beachy dance‑pop feel with tropical house influences. It could be perfect for a twin choreography or mirrored dance challenge, playing on the song''s theme. I''d be thrilled to see what you create and would love to provide the track! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"14.2M"}'),
  ('INFLUENCER', 'TikTok', 'Kelli Erdmann (HappyKelli)', 'hello@happykelli.com', 'OCEAN GIRL', 'Hi Kelli! Your upbeat tutorials and infectious energy always put a smile on viewers’ faces. I just released a new song ''OCEAN GIRL''—a dance‑pop tune with tropical house and alt‑pop influences. It has a catchy groove perfect for a feel‑good dance routine. I''d love to share the track and see if you''d like to choreograph a fun tutorial or challenge for your community. I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"9.3M"}'),
  ('INFLUENCER', 'TikTok', 'Niana Guerrero', 'contactniana@gmail.com', 'OCEAN GIRL', 'Hi Niana! Your dance collabs with your family and friends are always such a joy to watch. I recently released ''OCEAN GIRL,'' a summer‑ready dance‑pop song with tropical house vibes reminiscent of Kygo and Lauv. I could picture you and your brother creating a lively routine that captures the track''s feel‑good energy. I''d love to send it your way and hear what you think! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"46M"}'),
  ('INFLUENCER', 'TikTok', 'Nicole Laeno', 'lindalaeno@yahoo.com', 'OCEAN GIRL', 'Hey Nicole! Your blend of technical precision and modern style is really inspiring. My new single ''OCEAN GIRL'' mixes dance‑pop and alt‑pop influences (think The 1975 meets Kygo) with a bright, summery feel. I think your choreography could show a softer, emotive side while still being fun and dynamic. I''d love to share the track and explore a potential TikTok feature with you! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"5.7M"}'),
  ('INFLUENCER', 'TikTok', 'Bailey Sok', 'baileydreww@gmail.com', 'OCEAN GIRL', 'Hi Bailey! Your powerful moves and intricate footwork are always on another level. I''ve got a new track called ''OCEAN GIRL'' that blends dance‑pop with old‑school house and tropical influences. It has room for both sharp accents and smooth grooves—perfect for your style. I''d love to send you the song and see if you''d be interested in creating a routine! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"2.3M"}'),
  ('INFLUENCER', 'TikTok', 'Bea (Beablizen)', 'beaagustin655@gmail.com', 'OCEAN GIRL', 'Hello Bea! I came across your creative dance videos and love how you mix chillwave and R&B vibes. My new single ''OCEAN GIRL'' sits in a similar space between dance‑pop and tropical house, with a mellow edge. Would you be interested in making a dance or vibe video to help introduce the track to your audience? I''d be happy to share more details and the track with you. I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"74.5K"}'),
  ('INFLUENCER', 'TikTok', 'Jiji<3 (jiji.wonder)', 'jiji@tiddle.io', 'OCEAN GIRL', 'Hi Jiji! Your upbeat dance videos and positive messages really resonate with your followers. I just released a catchy dance‑pop song called ''OCEAN GIRL'' with house and chillwave influences. I think your spirited style would fit perfectly for a dance challenge around this track. Would you be interested in checking it out? I''d love to share the song with you! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"3.5M"}'),
  ('INFLUENCER', 'TikTok', 'NaeNae Twins', 'naenaetwins94@gmail.com', 'OCEAN GIRL', 'Hey NaeNae Twins! Your synchronised routines and trend‑setting moves always go viral. I''m reaching out with my new single ''OCEAN GIRL,'' a dance‑pop track infused with tropical house and alt‑pop influences. I can imagine a fun twin‑style choreography that reflects the playful beach vibes of the song. I''d love to send you the track and see if you''d like to collaborate on a TikTok challenge! I would love to see what you could come up with and would love to collaborate together to make something great!', '{"followers":"3.2M"}');
